def QuasiIdentity.Holds (q : QuasiIdentity) (G : Type) [Group G] : Prop :=
  ∀ x : ℕ → G, (∀ w ∈ q.premises, FreeGroup.lift x w = 1) →
    FreeGroup.lift x q.conclusion = 1

def SatisfiesQuasiIdentity (G : Type*) [Group G] (q : QuasiIdentity) : Prop :=
  ∀ f : ℕ → G, (∀ u ∈ q.premises, FreeGroup.lift f u = 1) →
    FreeGroup.lift f q.conclusion = 1

def Holds (q : QuasiIdentity) (H : Type*) [Group H] : Prop :=
  ∀ x : ℕ → H, (∀ p ∈ q.premises, FreeGroup.lift x p.1 = FreeGroup.lift x p.2) →
    FreeGroup.lift x q.conclusion.1 = FreeGroup.lift x q.conclusion.2

