def IsProOrderable (G : Type*) [Group G] : Prop :=
  ∀ r : G → G → Prop, IsPartialOrder G r → IsBiInvariant r →
    ∃ s : G → G → Prop, IsLinearOrder G s ∧ IsBiInvariant s ∧ ∀ a b : G, r a b → s a b

def IsProOrderable (G : Type*) [Group G] : Prop :=
  ∀ r : G → G → Prop, IsPartialOrder G r → IsBiInvariant r →
    ∃ s : G → G → Prop, IsLinearOrder G s ∧ IsBiInvariant s ∧ ∀ a b, r a b → s a b

def IsProOrderable (G : Type*) [Group G] : Prop :=
  ∀ p : PartialOrder G, IsBiInvariant p.le →
    ∃ l : LinearOrder G, IsBiInvariant l.le ∧ ∀ a b : G, p.le a b → l.le a b

def TilesByTranslations (P : Set (ℝ^d)) : Prop :=
  ∃ T : Set (ℝ^d), (⋃ t ∈ T, t +ᵥ P) = Set.univ ∧
    T.Pairwise fun s t => Disjoint (interior (s +ᵥ P)) (interior (t +ᵥ P))

def TilesByTranslation (P : Set ℝ³) : Prop :=
  ∃ T : Set ℝ³, (⋃ t ∈ T, t +ᵥ P) = Set.univ ∧
    T.Pairwise fun s t => Disjoint (interior (s +ᵥ P)) (interior (t +ᵥ P))

def IsTilingByTranslates (P T : Set (ℝ^d)) : Prop :=
  (⋃ t ∈ T, t +ᵥ P) = Set.univ ∧
    T.Pairwise fun t₁ t₂ => Disjoint (interior (t₁ +ᵥ P)) (interior (t₂ +ᵥ P))

def center (L : Type*) [Loop L] : Set L :=
  {a | ∀ x y : L, a * x = x * a ∧ a * x * y = a * (x * y) ∧
    x * a * y = x * (a * y) ∧ x * y * a = x * (y * a)}

def center (Q : Type u) [Loop Q] : Set Q :=
  {a | ∀ x y : Q, a * x = x * a ∧ a * x * y = a * (x * y) ∧ x * a * y = x * (a * y) ∧
    x * y * a = x * (y * a)}

def crossings (γ : ℝ → ℝ³) (u : ℝ³) : Set (ℝ × ℝ) :=
  {p | p.1 ∈ Set.Ico 0 1 ∧ p.2 ∈ Set.Ico 0 1 ∧ p.1 < p.2 ∧
    proj u (γ p.1) = proj u (γ p.2)}

def elementarySubgroup (m R : Type*) [DecidableEq m] [Fintype m] [CommRing R] :
    Subgroup (SpecialLinearGroup m R) :=
  Subgroup.closure (elementaryTransvections m R)

