def IsQuasivariety (𝔎 : GroupClass.{u}) : Prop :=
  ∃ Q : Set QuasiIdentity,
    ∀ (G : Type u) [Group G], 𝔎 G ↔ ∀ q ∈ Q, SatisfiesQuasiIdentity G q

noncomputable def discreteRelationRank (G : Type*) [Group G] [Group.FG G] : ℕ :=
  sInf {n : ℕ | ∃ S : Finset (FreeGroup (Fin (Group.rank G))),
    S.card = n ∧ Nonempty (PresentedGroup (S : Set (FreeGroup (Fin (Group.rank G)))) ≃* G)}

def IsRelativelyFree (F : Type*) [Group F] : Prop :=
  ∃ X : Set F, Subgroup.closure X = ⊤ ∧
    ∀ f : X → F, ∃ φ : F →* F, ∀ x : X, φ x = f x

def IsRelativelyFree (G : Type*) [Group G] : Prop :=
  ∃ X : Set G, Subgroup.closure X = ⊤ ∧
    ∀ f : X → G, ∃ φ : G →* G, ∀ x : X, φ x = f x

def Drawing.crossings (D : Drawing G) : Set (Sym2 G.edgeSet × ℝ²) :=
  {c | ∃ e f : G.edgeSet, e ≠ f ∧ c.1 = s(e, f) ∧
    c.2 ∈ D.arc e '' Set.Ioo 0 1 ∧ c.2 ∈ D.arc f '' Set.Ioo 0 1}

